mapper.sql:
SELECT ACAD.* , ROW_NUMBER() OVER(ORDER BY TO_DATE(ACAD.REG_DTTM, 'YYYYMMDDHH24MISS') DESC) AS "LINE_NO" /* Row Number */ , O.ORGNM , SC.SMSTR_CHRTNM FROM TB_LMS_ACAD_SCHDL ACAD JOIN TB_LMS_ORG O ON ACAD.ORG_ID = O.ORG_ID LEFT JOIN TB_LMS_SMSTR_CHRT SC ON ACAD.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID WHERE 1 = 1
AND ACAD.ORG_ID = #{orgId}
AND ACAD.SMSTR_CHRT_ID = #{smstrChrtId}
AND ( ACAD.SCHDL_EXPLN LIKE '%'||#{searchText}||'%' )

mapper.delete:
/*	설명 : 학사일정삭제 	*/		
DELETE 
FROM	TB_LMS_ACAD_SCHDL	ACAD
WHERE	ACAD.ACAD_SCHDL_ID = #{acadSchdlId}

mapper.insert:
	/*	설명 : 학사일정등록 	*/
	INSERT INTO TB_LMS_ACAD_SCHDL (
          ACAD_SCHDL_ID
        , ORG_ID
        , ACAD_SCHDL_SDTTM
        , ACAD_SCHDL_EDTTM
        , ACAD_SCHDL_TYCD
        , ACAD_SCHDL_EXPLN
        , RGTR_ID
        , REG_DTTM
        , SMSTR_CHRT_ID
    ) VALUES (
          #{acadSchdlId}
        , #{orgId}
        , #{acadSchdlSdttm}
        , #{acadSchdlEdttm}
        , #{acadSchdlTycd}
        , #{acadSchdlExpln}
        , #{rgtrId}
        , TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS')
        , #{smstrChrtId}
    )

mapper.update:
/*	설명 : 학사일정수정 	*/		
UPDATE TB_LMS_ACAD_SCHDL
   SET 
       ACAD_SCHDL_SDTTM = #{acadSchdlSdttm}
     , ACAD_SCHDL_EDTTM = #{acadSchdlEdttm}
     , ACAD_SCHDL_TYCD  = #{acadSchdlTycd}
     , ACAD_SCHDL_EXPLN = #{acadSchdlExpln}
     , SMSTR_CHRT_ID    = #{smstrChrtId}
     , MDFR_ID          = #{mdfrId}
     , MOD_DTTM         = TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS')
 WHERE ACAD_SCHDL_ID    = #{acadSchdlId}

mapper.select:
/*	설명 : 학사일정조회 	*/		
SELECT	ACAD.*
FROM	TB_LMS_ACAD_SCHDL ACAD
